            }
            Value::Table(t) => {
                let _guard = RecursionGuard::new(&t, &self.visited);

                let len = self.len.unwrap_or_else(|| t.raw_len());
                let mut deserializer = SeqDeserializer {
                    seq: t.sequence_values().with_len(len),
                    options: self.options,
                    visited: self.visited,
